import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to a wide range that is still payable and keeps the reference behavior safe.
        // The reference forwards the whole balance after the external call. To isolate the difference,
        // we must ensure the external call to the fixed target succeeds. The target 0xC8A60... is an EOA
        // (no code) so low-level calls always succeed. We avoid overflow by bounding below max balance.
        vm.assume(amount > 0);
        amount = bound(amount, 1, 1000 ether);

        address ownerBefore = c.owner();
        uint256 ownerBalanceBefore = ownerBefore.balance;

        // Fund the caller and call go() with the fuzzed amount.
        address caller = makeAddr("caller");
        vm.deal(caller, amount);
        vm.prank(caller);
        c.go{value: amount}();

        // After the call, the reference transfers the entire contract balance (which is exactly amount,
        // since the external call succeeds without consuming gas value) to the owner.
        // The buggy version transfers a fixed 1 ether instead.
        uint256 ownerBalanceAfter = ownerBefore.balance;
        uint256 balanceIncrease = ownerBalanceAfter - ownerBalanceBefore;
        assertTrue(balanceIncrease == amount);
    }
}

