import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // The reference C always forwards the entire remaining balance to owner after the external call,
        // which equals msg.value because the target call always succeeds with no other payers.
        // The buggy version always transfers 1 ether, so it deviates when amount != 1 ether.
        // Admissible domain: amount > 0 so an actual transfer occurs;
        // also bounded to avoid integer overflow in owner balance tracking (but we assert on delta).
        vm.assume(amount > 0 && amount <= 1_000_000 ether);
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;
        vm.deal(address(this), amount);
        c.go{value: amount}();
        uint256 ownerAfter = owner.balance;
        // Rule: owner's balance increases by exactly the amount forwarded to go().
        // The reference satisfies this for all admissible amounts; the bug fails when amount != 1 ether.
        assertEq(ownerAfter - ownerBefore, amount, "owner balance delta must equal msg.value");
    }
}

