contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, bool shouldFail) public {
        vm.assume(amount <= address(this).balance);
        // Deploy an adversarial callee that can fail or succeed based on fuzzed input
        Reverter reverter = new Reverter();
        address target = shouldFail ? address(reverter) : address(0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C);

        // Setup: fund actor and contract (contract needs >= amount for call)
        vm.deal(address(this), amount + 1 ether);
        vm.deal(address(c), amount + 1 ether);

        // Record owner balance before
        address own = c.owner();
        uint256 ownerBalBefore = own.balance;

        // Drive through go and capture result
        bool success;
        try c.go{value: amount}() {
            success = true;
        } catch {
            success = false;
        }

        uint256 contractBalAfter = address(c).balance;
        uint256 ownerBalAfter = own.balance;

        // The rule: after go(), owner balance has increased by at least the contract balance before the call.
        // The buggy version fails this when the external call fails, because require is missing,
        // so the owner receives nothing while the contract's balance is drained.
        if (success) {
            assertTrue(ownerBalAfter == ownerBalBefore + amount + contractBalAfter);
        } else {
            // For the correct version, a failed call should revert, so the state remains unchanged.
            // The test expects failure mode to revert; the bug allows non-revert on failure.
            assertTrue(false);
        }
    }
}

