import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow/insufficient balance issues
        amount = bound(amount, 1, 1000 ether);
        vm.deal(address(this), amount);
        vm.deal(address(c), 0);

        // Record balance before call
        uint256 initialBalance = address(c).balance;

        // Perform the call
        c.go{value: amount}();

        // After successful call, the contract's balance must be zero
        // because all remaining Ether is transferred to the owner.
        // The buggy version selfdestructs, sending the remaining balance to the owner,
        // but then the transfer fails because the contract is destroyed, leaving balance unchanged.
        assertEq(address(c).balance, 0, "Contract balance should be zero after successful go()");
    }
}

