pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool targetReverts) public {
        vm.assume(amount > 0);
        // Adversarial helper: either a fallback that always reverts, or a normal EOA-like that succeeds.
        // The fuzzer chooses which via the boolean parameter.
        // Deploy the helper
        address targetAddress;
        if (targetReverts) {
            targetAddress = address(new RevertingTarget());
        } else {
            targetAddress = address(new AcceptingTarget());
        }
        // Create a new C instance for this fuzz run so that owner is set correctly
        vm.deal(address(this), amount);
        c = new C();
        // Fund the contract so it has balance before the call
        vm.prank(msg.sender);
        (bool fundSuccess, ) = address(c).call{value: amount}("");
        require(fundSuccess, "funding failed");
        // Drive go() with the fuzzed value
        vm.prank(msg.sender);
        try c.go{value: amount}() {
            // succeeded
        } catch {
            // reverted
        }
        // The invariant: after go(), the contract's own balance must be zero.
        assertTrue(address(c).balance == 0);
    }
}

contract RevertingTarget {
    fallback() external payable {
        revert("adversarial revert");
    }
}

