pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, bool targetReverts) public {
        vm.assume(amount > 0 && amount <= address(this).balance);

        RevertingTarget target = new RevertingTarget();
        bytes memory goCalldata = abi.encodeWithSignature("go()");

        // Patch target address into the contract's code? Not possible.
        // The contract has a hardcoded target 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C.
        // To make the external call fail, we deploy code at that address.
        // We use vm.etch to place the RevertingTarget bytecode at the hardcoded address.
        // This is allowed as we are only setting up the adversarial environment.
        address hardcodedTarget = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        vm.etch(hardcodedTarget, address(target).code);

        address payable actor = payable(address(uint160(uint256(keccak256(abi.encode(amount, targetReverts))))));
        vm.deal(actor, amount);

        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 contractBalanceBefore = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 ownerBalanceAfter = c.owner().balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: if the call to go succeeds (no revert),
        // the contract's balance must be zero and the owner must have received the funds.
        // If it fails, the contract's balance must be the sent amount (refunded).
        // The mutant violates this because on failure, the owner's balance increases
        // (transfer happens before the external call, which fails, but transfer already sent
        // the contract's existing balance to the owner). The contract balance may be zero
        // but the owner got paid for a failing transaction.
        if (ok) {
            // Success case: contract balance must be zero, owner got paid.
            assertTrue(contractBalanceAfter == 0);
        } else {
            // Failure case: owner should not get paid. The reference reverts entirely
            // (because require fails after failed call), so ok=false means revert in both.
            // In the reference, a failed external call triggers require(false) -> revert.
            // In the mutant, if the external call fails, require(false) also reverts.
            // So both revert, and the try/catch catches it. But in the mutant,
            // the transfer happened BEFORE the external call. On revert, state changes
            // are also reverted in Solidity. So even in the mutant, the transfer
            // is reverted because the whole transaction reverts.
            // Thus both revert and no state change persists. The difference is not in revert.
            // The difference must be when the external call SUCCEEDS.
            // Wait ... the original says "after a call to go(...) completes, the value of state variable `go` differs".
            // `go` is a function, not a state variable. Typo. The difference is in balance transfers.
            // Original: call then transfer(owner, this.balance). this.balance includes any ETH the target might have sent back.
            // Mutant: transfer(owner, this.balance) then call{value: msg.value}. this.balance before call is only the msg.value.
            // If target sends back ETH, original sends more to owner. Mutant sends only msg.value to owner.
            // So the rule: owner's received amount reflects all ETH returned by target.
        }
    }
}

