pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 priorBalance) public {
        vm.assume(amount >= 0);
        vm.assume(priorBalance >= 0);
        // Deploy an adversarial callee that always reverts
        Reverter reverter = new Reverter();
        // Give the contract some prior balance
        vm.deal(address(c), priorBalance);
        // Fund the caller and call go() on the adversarial target
        vm.deal(address(this), amount);
        bool ok;
        try c.go{value: amount}() { ok = true; } catch { ok = false; }
        // If the call did not revert, the contract's balance must be zero
        assertTrue(!ok || address(c).balance == 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
